using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using Deception.Core;
using Deception.PolyModAdapter;
namespace Deception.Tests
{
 public static partial class BlackmailTests
 {
  static int Assertions;static List<string> Cases=new();
  static void Check(bool yes,string why){Assertions++;if(!yes)throw new Exception(why);}
  static void Test(string name,Action body){try{Fault.At="";NativeBlackmail.Clear();NativeRegroupSession.Enabled=true;NativeRegroupSession.Owned.Clear();NativeRegroupSession.Faults.Clear();NativeGameStateEnvelope.Values.Clear();NativeExchangeCommands.Executing=null;RecruitmentHooks.Registered=true;body();Cases.Add(name);}catch(Exception e){throw new Exception(name,e);}}
  static GameState Make()
  {
   var s=new GameState();s.Players.AddRange(new byte[]{1,2,3,4}.Select(id=>new PlayerState{Id=id}));
   s.Map.Tiles.AddRange(new[]{new TileData{coordinates=new(2,3)},new TileData{coordinates=new(3,2)},new TileData{coordinates=new(4,4),owner=3}});
   for(int n=0;n<s.Map.Tiles.Count;n++){var t=s.Map.Tiles[n];t.unit=new(){id=(uint)(101+n),owner=t.owner,home=t.coordinates,coordinates=t.coordinates};}
   var ledger=new NativeIdentityLedger(Guid.Parse("93021e17-da4b-4193-bc03-2b4d75eab686"),4,1,s.Map.Tiles.Select((t,n)=>new LedgerUnit((ulong)(n+1),t.unit!.id,true,LedgerActualKind.Genuine,false,null,PaidInvestmentKind.Known,2)).ToArray(),Array.Empty<LedgerReceipt>());
   NativeGameStateEnvelope.Set(s,0,NativeIdentityLedgerCodec.Encode(ledger,0));NativeRegroupSession.Owned.Add(s);return s;
  }
  static PlayerState P(GameState s,byte p)=>s.Players.Single(x=>x.Id==p);
  static TileData City(GameState s,int i=0)=>s.Map.Tiles[i];
  static NativeGameStateEnvelope.Snapshot Snap(GameState s)=>NativeGameStateEnvelope.Get(s)!;
  static NativeIdentityLedger Read(GameState s)=>NativeIdentityLedgerCodec.Decode(Snap(s).Bytes(),Snap(s).Revision);
  static void Write(GameState s,NativeIdentityLedger l)=>NativeGameStateEnvelope.Set(s,Snap(s).Revision,NativeIdentityLedgerCodec.Encode(l,Snap(s).Revision));
  static UnitState Target(GameState s,int i=0)=>City(s,i).unit!;
  static LedgerBlackmail Mark(GameState s,LedgerBlackmail r){if(r.UnitId>0)return r;var t=s.Map.Tiles.Single(t=>t.coordinates.X==r.X&&t.coordinates.Y==r.Y);t.unit!.owner=r.Victim;return r with{UnitId=Read(s).Units.Single(u=>u.NativeId==t.unit.id).LogicalId,LastAppliedTurn=r.CreatedTurn};}
  static void Rows(GameState s,params LedgerBlackmail[] rows)=>Write(s,Read(s) with{Blackmails=rows.Select(r=>Mark(s,r)).OrderBy(r=>r.X).ThenBy(r=>r.Y).ThenBy(r=>r.Blackmailer).ThenBy(r=>r.UnitId).ToArray()});
  static NativeExchangeIntent Offer(GameState s,byte p=1,int i=0){Check(NativeBlackmail.TryOffer(s,p,Target(s,i),out var request,out var why),why);return request!;}
  static bool Commit(GameState s,NativeExchangeIntent i,out NativeExchangeCommitResult? r,out string why)
  {NativeExchangeCommands.Executing=s;try{return NativeBlackmail.TryCommit(s,i,out r,out why);}finally{NativeExchangeCommands.Executing=null;}}
  static void DrainEmbassies(GameState s){foreach(var child in s.ActionStack.OfType<DestroyEmbassyAction>().ToArray()){child.Execute(s);s.ActionStack.Remove(child);}}
  static NativeExchangeIntent Buy(GameState s,byte p=1,int i=0){var request=Offer(s,p,i);Check(Commit(s,request,out _,out var why),why);DrainEmbassies(s);return request;}
  static void Marker(GameState s,byte old=1,CommandType kind=CommandType.EndTurn)
  {
   var a=new EndCommandAction{PlayerId=old,commandType=kind};s.ActionStack.Add(a);NativeBlackmail.BeforeSettlement(a,s,out var scope);a.Execute(s);NativeBlackmail.AfterNative(true,scope);var e=NativeBlackmail.Finished(null,scope);s.ActionStack.Remove(a);if(e is not null)throw e;
  }
  static NativeBlackmail.ActionScope? Start(GameState s,EndCommandAction? a=null){a??=new();s.ActionStack.Add(a);NativeBlackmail.BeforeSettlement(a,s,out var scope);NativeBlackmail.AfterNative(true,scope);return scope;}
  static void Cleanup(GameState s,Action mutate,ActionBase? a=null)
  {a??=new CaptureCityAction();s.ActionStack.Add(a);NativeBlackmail.BeforeCleanup(a,s,out var scope);mutate();NativeBlackmail.AfterNative(true,scope);var e=NativeBlackmail.Finished(null,scope);s.ActionStack.Remove(a);if(e is not null)throw e;}
  public static int Run(){try{
   Test("BLACKMAIL-001-native-safe-hooks",()=>{var h=new HarmonyLib.Harmony();NativeBlackmail.Install(h);Check(h.Hooks.SequenceEqual(new[]{"EndCommandAction.Execute","CaptureCityAction.Execute","DestroyImprovementAction.Execute","WipePlayerAction.Execute","PeaceRequestResponseAction.Execute"}),"exact reference/void hooks");});
   Test("BLACKMAIL-002-visible-unit-offer-is-read-only",()=>{var s=Make();var snap=Snap(s);var i=Offer(s);Check(i.Kind==NativeExchangeKind.Blackmail&&i.Initiator==new NativeExchangeUnit(1,101,2,3)&&i.Partner==i.Initiator,"unit canonical intent");Check(NativeExchangeIntentCodec.Encode(i).Length==136,"existing intent frame retained");Check(ReferenceEquals(snap,Snap(s))&&P(s,1).Currency==20,"offer has no enrollment/debit");});
   Test("BLACKMAIL-003-setup-debits-two-once-no-action-budget",()=>{var s=Make();var i=Buy(s);var row=Read(s).Blackmails!.Single();Check(P(s,1).Currency==18&&P(s,2).Currency==20&&row==new LedgerBlackmail(1,2,2,3,4,UnitId:1,LastAppliedTurn:4),"two stars and persistent pair");Check(!s.UnitMoved&&!s.UnitAttacked&&!s.CityExhausted,"no unit/city action spend");var receipt=Read(s).Receipts.Single();Check(receipt.Affected.SequenceEqual(new ulong[]{1})&&receipt.City is null,"unit durable receipt");var snap=Snap(s);Check(Commit(s,i,out var r,out _)&&r!.AlreadyCommitted&&ReferenceEquals(snap,Snap(s))&&P(s,1).Currency==18,"duplicate receipt has no debit");var exact=Make();P(exact,1).Currency=2;Buy(exact);Check(P(exact,1).Currency==0,"exactly two stars buys one layer without overdraft");});
   foreach(string invalid in new[]{"research","hidden","self","neutral","victim-dead","actor-dead","missing-actor","missing-victim","cost","turn","ended","unowned","disabled","unregistered","missing-ledger","foreign-tile"})Test("BLACKMAIL-004-offer-denial-"+invalid,()=>{var s=Make();UnitState unit=Target(s);TileData tile=City(s);switch(invalid){case"research":P(s,1).Espionage=false;break;case"hidden":tile.Visible.Remove(1);break;case"self":unit.owner=1;break;case"neutral":unit.owner=0;break;case"victim-dead":P(s,2).Alive=false;break;case"actor-dead":P(s,1).Alive=false;break;case"missing-actor":s.Players.Remove(P(s,1));break;case"missing-victim":s.Players.Remove(P(s,2));break;case"cost":P(s,1).Currency=1;break;case"turn":s.CurrentPlayer=3;break;case"ended":s.CurrentState=GameState.State.Ended;break;case"unowned":NativeRegroupSession.Owned.Remove(s);break;case"disabled":NativeRegroupSession.Enabled=false;break;case"unregistered":RecruitmentHooks.Registered=false;break;case"missing-ledger":NativeGameStateEnvelope.Values.Remove(s);break;case"foreign-tile":unit=new(){id=unit.id,coordinates=tile.coordinates,home=unit.home};break;}Check(!NativeBlackmail.TryOffer(s,1,unit,out _,out _),"invalid city command not offered");});
   Test("BLACKMAIL-005-one-pair-many-opponents-many-cities",()=>{var s=Make();Buy(s);Check(!NativeBlackmail.TryOffer(s,1,Target(s),out _,out _),"duplicate pair refused");Buy(s,1,1);s.CurrentPlayer=3;Buy(s,3);Check(Read(s).Blackmails!.Length==3&&P(s,1).Currency==16&&P(s,3).Currency==18,"independent setup fees per paircity");});
   Test("BLACKMAIL-006-plan-preserves-unit-and-home-identities",()=>{var s=Make();var i=Offer(s);Check(NativeBlackmail.TryPlan(s,i,out var p,out _),"plans");Check(ReferenceEquals(p!.A,Target(s))&&ReferenceEquals(p.A,p.B)&&ReferenceEquals(p.TileA,City(s))&&ReferenceEquals(p.TileA,p.TileB),"exact unit and supporting city endpoints");Check(p.CandidateLedger.Units.Length==3&&p.CandidateLedger.NextLogicalId==4,"no unit allocation");});
   Test("BLACKMAIL-007-direct-commit-needs-execution-authority",()=>{var s=Make();var i=Offer(s);Check(!NativeBlackmail.TryCommit(s,i,out _,out _),"no command scope");var other=Make();NativeExchangeCommands.Executing=other;Check(!NativeBlackmail.TryCommit(s,i,out _,out _)&&P(s,1).Currency==20,"foreign command scope refused");});
   foreach(string stale in new[]{"currency","owner","turn","actor","fog","epoch","revision","ledger","sequence"})Test("BLACKMAIL-008-stale-"+stale,()=>{var s=Make();var i=Offer(s);switch(stale){case"currency":P(s,1).Currency++;break;case"owner":City(s).owner=3;break;case"turn":s.CurrentTurn++;break;case"actor":s.CurrentPlayer=3;break;case"fog":City(s).Visible.Clear();break;case"epoch":Write(s,Read(s) with{Epoch=Guid.NewGuid()});break;case"revision":NativeGameStateEnvelope.Set(s,1,NativeIdentityLedgerCodec.Encode(Read(s),1));break;case"ledger":Write(s,Read(s) with{Blackouts=new[]{new LedgerBlackout(2,4,4)}});break;case"sequence":i=i with{Sequence=2};break;}int old=P(s,1).Currency;Check(!Commit(s,i,out _,out _)&&P(s,1).Currency==old&&Read(s).Blackmails!.Length==0,"stale intent rejected without debit");});
   Test("BLACKMAIL-009-native-income-children-before-end-marker",()=>{var s=Make();Buy(s);P(s,2).Currency=0;s.CurrentPlayer=2;var marker=new EndCommandAction{PlayerId=1};s.ActionStack.Add(marker);s.ActionStack.Add(new IncreaseCurrencyAction{PlayerId=2,Amount=7});Check(P(s,1).Currency==18&&Read(s).Blackmails![0].LastPaidTurn==-1,"StartTurn only queues native income");var income=(IncreaseCurrencyAction)s.ActionStack[^1];income.Execute(s);s.ActionStack.RemoveAt(s.ActionStack.Count-1);NativeBlackmail.BeforeSettlement(marker,s,out var scope);marker.Execute(s);NativeBlackmail.AfterNative(true,scope);Check(NativeBlackmail.Finished(null,scope) is null&&P(s,1).Currency==18&&P(s,2).Currency==6,"new player pays after income despite marker old PlayerId");Check(Snap(s).Revision==1&&Read(s).Blackmails![0].LastPaidTurn==4,"event same revision and paid turn persisted");});
   Test("BLACKMAIL-010-unrelated-end-command-does-not-pay",()=>{var s=Make();Buy(s);s.CurrentPlayer=2;Marker(s,1,CommandType.Build);Marker(s,1,CommandType.Resign);Check(P(s,1).Currency==18&&Read(s).Blackmails![0].LastPaidTurn==-1,"only native EndTurn completion");});
   Test("BLACKMAIL-011-duplicate-markers-same-turn-noop-next-turn-pays",()=>{var s=Make();Buy(s);s.CurrentPlayer=2;Marker(s);var snap=Snap(s);Marker(s);Check(P(s,1).Currency==18&&ReferenceEquals(snap,Snap(s)),"duplicate completion no payment/publish");s.CurrentTurn++;Marker(s);Check(P(s,1).Currency==18&&P(s,2).Currency==18,"next owner turn pays once");});
   Test("BLACKMAIL-012-lost-vision-still-pays-with-no-fog-change",()=>{var s=Make();Buy(s);City(s).Visible.Clear();s.CurrentPlayer=2;Marker(s);Check(P(s,1).Currency==18&&City(s).Visible.Count==0,"ongoing payment neither requires nor creates vision");Check(NativeBlackmail.All(s).Length==1,"read-only rows available for visibility-filtered UI");});
   Test("BLACKMAIL-013-canonical-shortage-city-then-blackmailer",()=>{var s=Make();Rows(s,new LedgerBlackmail(4,2,3,2,4),new(3,2,2,3,4),new(1,2,2,3,4));P(s,2).Currency=2;s.CurrentPlayer=2;Marker(s);Check(P(s,1).Currency==20&&P(s,3).Currency==20&&P(s,4).Currency==20&&P(s,2).Currency==0,"victim own-turn deduction saturates at zero, no out-of-turn credits");Check(Read(s).Blackmails!.All(r=>r.LastPaidTurn==4),"unpaid installment is settled, not debt");P(s,2).Currency=10;Marker(s);Check(P(s,4).Currency==20&&P(s,2).Currency==10,"later gift cannot retry installment");});
   Test("BLACKMAIL-014-only-current-city-owner-pays",()=>{var s=Make();Rows(s,new LedgerBlackmail(1,2,2,3,4),new(1,3,4,4,4));s.CurrentPlayer=2;Marker(s,3);Check(P(s,1).Currency==20&&P(s,2).Currency==19&&P(s,3).Currency==20,"marker old actor does not choose debtor");Check(Read(s).Blackmails!.Single(r=>r.Victim==3).LastPaidTurn==-1,"other debtor pending");});
   Test("BLACKMAIL-015-zero-treasury-never-overdrawn",()=>{var s=Make();Rows(s,new LedgerBlackmail(1,2,2,3,4));P(s,2).Currency=0;s.CurrentPlayer=2;Marker(s);Check(P(s,2).Currency==0&&P(s,1).Currency==20&&Read(s).Blackmails![0].LastPaidTurn==4,"zero funds zero transfer settled");});
   Test("BLACKMAIL-016-beneficiary-overflow-does-not-destroy-star",()=>{var s=Make();Rows(s,new LedgerBlackmail(1,2,2,3,4),new(3,2,2,3,4));P(s,1).Currency=int.MaxValue;P(s,2).Currency=1;s.CurrentPlayer=2;Marker(s);Check(P(s,1).Currency==int.MaxValue&&P(s,2).Currency==0&&P(s,3).Currency==20,"no out-of-turn credit even when a beneficiary is full");});
   foreach(string why in new[]{"capture","destroy","victim-dead","blackmailer-dead","blackmailer-missing"})Test("BLACKMAIL-017-prune-"+why,()=>{var s=Make();Buy(s);Cleanup(s,()=>{switch(why){case"capture":City(s).owner=3;break;case"destroy":City(s).City=false;break;case"victim-dead":P(s,2).Alive=false;break;case"blackmailer-dead":P(s,1).Alive=false;break;case"blackmailer-missing":s.Players.Remove(P(s,1));break;}},why=="destroy"?new DestroyImprovementAction():why.Contains("dead")||why.Contains("missing")?new WipePlayerAction():new CaptureCityAction());Check(Read(s).Blackmails!.Length==0,"invalid relationship removed durably");s.CurrentPlayer=2;Marker(s);Check(P(s,2).Currency==20,"pruned city no longer pays");});
   Test("BLACKMAIL-018-recapture-does-not-resurrect",()=>{var s=Make();Buy(s);Cleanup(s,()=>City(s).owner=3);Cleanup(s,()=>City(s).owner=2);s.CurrentPlayer=2;Marker(s);Check(P(s,1).Currency==18&&Read(s).Blackmails!.Length==0,"capture/recapture cannot revive old agreement");});
   Test("BLACKMAIL-019-new-owner-setup-replaces-stale-owner-rows",()=>{var s=Make();Rows(s,new LedgerBlackmail(3,2,2,3,4));City(s).owner=4;Check(!NativeBlackmail.TryOffer(s,1,Target(s),out _,out _),"old owner unit cannot siphon captured home");Target(s).owner=4;Buy(s);Check(Read(s).Blackmails!.Single()==new LedgerBlackmail(1,4,2,3,4,UnitId:1,LastAppliedTurn:4),"new setup atomically removes outdated owner to preserve codec invariant");});
   foreach(string failure in new[]{"currency1","ledger","validate"})Test("BLACKMAIL-020-setup-rollback-"+failure,()=>{var s=Make();var i=Offer(s);var before=Snap(s);Fault.At=failure;Check(!Commit(s,i,out _,out _),"injected failure rejected");Check(P(s,1).Currency==20&&Snap(s).Revision==before.Revision&&Snap(s).Bytes().SequenceEqual(before.Bytes()),"treasury and exact envelope restored");Check(Commit(s,i,out _,out _),"same authorized intent retries after clean rollback");});
   foreach(string failure in new[]{"currency2","ledger","validate"})Test("BLACKMAIL-021-settlement-rollback-"+failure,()=>{var s=Make();Rows(s,new LedgerBlackmail(1,2,2,3,4),new(3,2,3,2,4));s.CurrentPlayer=2;var before=Snap(s);var scope=Start(s);Fault.At=failure;Check(NativeBlackmail.Finished(null,scope) is not null,"event failure surfaced");Check(s.Players.All(p=>p.Currency==20)&&Snap(s).Bytes().SequenceEqual(before.Bytes()),"all debit/credits and LastPaidTurn rollback");Check(NativeRegroupSession.Faults.Count==1,"failed economy quarantines current session");});
   foreach(string invalid in new[]{"unqueued","removed","exception","skipped","generation","map","turn","player","epoch","retired"})Test("BLACKMAIL-022-event-scope-denial-"+invalid,()=>{var s=Make();Rows(s,new LedgerBlackmail(1,2,2,3,4));s.CurrentPlayer=2;var a=new EndCommandAction();NativeBlackmail.ActionScope? scope;if(invalid=="unqueued"){NativeBlackmail.BeforeSettlement(a,s,out scope);Check(scope is null,"unqueued marker ignored");return;}scope=Start(s,a);Exception? error=null;switch(invalid){case"removed":s.ActionStack.Remove(a);break;case"exception":error=new Exception("native");break;case"skipped":scope!.Ran=false;break;case"generation":NativeBlackmail.Clear();break;case"map":s.Map=new();break;case"turn":s.CurrentTurn++;break;case"player":s.CurrentPlayer=3;break;case"epoch":Write(s,Read(s) with{Epoch=Guid.NewGuid()});break;case"retired":NativeRegroupSession.Owned.Remove(s);break;}Check(ReferenceEquals(error,NativeBlackmail.Finished(error,scope))&&P(s,1).Currency==20&&P(s,2).Currency==20,"invalid callback cannot transfer");});
   Test("BLACKMAIL-023-double-finalizer-is-noop",()=>{var s=Make();Rows(s,new LedgerBlackmail(1,2,2,3,4));s.CurrentPlayer=2;var scope=Start(s);Check(NativeBlackmail.Finished(null,scope) is null,"first completion");var snap=Snap(s);Check(NativeBlackmail.Finished(null,scope) is null&&ReferenceEquals(snap,Snap(s))&&P(s,1).Currency==20,"second completion no mutation");});
   Test("BLACKMAIL-024-save-reload-paid-turn-is-durable",()=>{var s=Make();Buy(s);s.CurrentPlayer=2;Marker(s);var snap=Snap(s);var restored=Make();restored.CurrentPlayer=2;foreach(var p in restored.Players)p.Currency=P(s,p.Id).Currency;NativeGameStateEnvelope.Set(restored,snap.Revision,snap.Bytes());Marker(restored);Check(P(restored,1).Currency==18&&P(restored,2).Currency==19,"restored pending duplicate marker no repayment");restored.CurrentTurn++;Marker(restored);Check(P(restored,1).Currency==18&&P(restored,2).Currency==18,"saved relationship survives to next turn");});
   Test("BLACKMAIL-025-read-only-city-list-filters-without-publish",()=>{var s=Make();Rows(s,new LedgerBlackmail(1,2,2,3,4),new(3,2,3,2,4));var snap=Snap(s);City(s,1).owner=4;var all=NativeBlackmail.All(s);Check(all.Length==1&&NativeBlackmail.At(s,City(s)).Length==1&&NativeBlackmail.At(s,new TileData{coordinates=City(s).coordinates}).Length==0,"read-only matching city and current owner only");all[0]=all[0] with{Victim=4};Check(Read(s).Blackmails![0].Victim==2&&ReferenceEquals(snap,Snap(s)),"caller array cannot mutate persistent ledger");});
   Test("BLACKMAIL-026-empty-ledger-action-hook-is-inert",()=>{var s=Make();var a=new EndCommandAction();s.ActionStack.Add(a);NativeBlackmail.BeforeSettlement(a,s,out var scope);Check(scope is null,"no payout scope allocated with no records");Check(NativeBlackmail.Finished(null,scope) is null&&P(s,1).Currency==20,"native action untouched");});
   Test("BLACKMAIL-027-zero-unit-city-intent-roundtrip",()=>{var s=Make();var i=Offer(s);var copy=NativeExchangeIntentCodec.Decode(NativeExchangeIntentCodec.Encode(i));Check(Commit(s,copy,out _,out _),"serialized command still commits native city setup");Check(NativeExchangeIntentCodec.AlreadyCommitted(Read(s),Snap(s).Revision,copy),"exact durable city receipt recognized");});
   Test("BLACKMAIL-028-recreated-native-player-wrappers-aggregate-by-ID",()=>{var s=Make();s.Rewrap=true;Rows(s,new LedgerBlackmail(1,2,2,3,4),new(1,2,3,2,4));s.CurrentPlayer=2;Marker(s);Check(P(s,1).Currency==20&&P(s,2).Currency==18,"two cities debit current victim twice despite fresh wrappers");});
   Test("BLACKMAIL-029-snapshot-read-cache-keeps-no-history-rescans",()=>{var s=Make();Rows(s,new LedgerBlackmail(1,2,2,3,4));var snap=Snap(s);NativeBlackmail.All(s);int reads=snap.Reads;NativeBlackmail.All(s);NativeBlackmail.At(s,City(s));var a=new EndCommandAction();s.ActionStack.Add(a);NativeBlackmail.BeforeSettlement(a,s,out var scope);Check(snap.Reads==reads,"All/At/event admission share immutable snapshot rows");var before=NativeBlackmail.All(s);Write(s,Read(s) with{Blackmails=Array.Empty<LedgerBlackmail>()});Check(NativeBlackmail.All(s).Length==0&&before.Length==1,"same-revision snapshot replacement invalidates cache");});
   Test("BLACKMAIL-030-invalid-queued-native-marker-is-inert",()=>{var s=Make();Rows(s,new LedgerBlackmail(1,2,2,3,4));s.CurrentPlayer=2;var a=new EndCommandAction{Valid=false};s.ActionStack.Add(a);NativeBlackmail.BeforeSettlement(a,s,out var scope);Check(scope is null&&P(s,1).Currency==20,"native validity required before settling");});
   Test("BLACKMAIL-031-setup-turn-has-no-retroactive-income",()=>{var s=Make();Buy(s);Marker(s,4);Check(P(s,1).Currency==18&&P(s,2).Currency==20&&Read(s).Blackmails![0].LastPaidTurn==-1,"beneficiary waits for victim turn");s.CurrentPlayer=2;Marker(s,1);Check(P(s,1).Currency==18&&P(s,2).Currency==19,"victim loses income without crediting actor outside own turn");});
   Test("BLACKMAIL-032-own-turn-credits-each-city-once",()=>{var s=Make();Buy(s);Buy(s,1,1);s.CurrentPlayer=2;Marker(s);Check(P(s,1).Currency==16&&P(s,2).Currency==18,"victim debited without actor credit");s.CurrentTurn=5;s.CurrentPlayer=1;Marker(s,4);Check(P(s,1).Currency==18&&P(s,2).Currency==18&&Read(s).Blackmails!.All(r=>r.LastCollectedTurn==5),"actor earns two own-turn stars");var snapshot=Snap(s);Marker(s,4);Check(ReferenceEquals(snapshot,Snap(s))&&P(s,1).Currency==18,"no duplicate collection");});
   Test("BLACKMAIL-033-own-turn-income-does-not-depend-on-victim-treasury",()=>{var s=Make();Buy(s);P(s,2).Currency=0;s.CurrentTurn=5;Marker(s);Check(P(s,1).Currency==19&&P(s,2).Currency==0,"embassy-style own-turn income with no negative victim treasury");});
   Test("BLACKMAIL-034-simultaneous-own-income-and-own-obligations-net-once",()=>{var s=Make();City(s,2).owner=1;Rows(s,new(1,2,2,3,4),new(1,2,3,2,4),new(3,1,4,4,4));s.CurrentTurn=5;P(s,1).Currency=0;Marker(s);Check(P(s,1).Currency==1&&P(s,2).Currency==20&&P(s,3).Currency==20,"two incoming one outgoing on own turn");Check(Read(s).Blackmails!.All(r=>r.Blackmailer==1?r.LastCollectedTurn==5:r.LastPaidTurn==5),"each independent stamp recorded");});
   Test("BLACKMAIL-035-own-income-overflow-saturates-and-never-retries",()=>{var s=Make();Rows(s,new LedgerBlackmail(1,2,2,3,4));s.CurrentTurn=5;P(s,1).Currency=int.MaxValue;Marker(s);P(s,1).Currency=20;Marker(s);Check(P(s,1).Currency==20&&Read(s).Blackmails!.Single().LastCollectedTurn==5,"overflow is settled, no deferred debt");});
   foreach(string failure in new[]{"currency1","ledger","validate"})Test("BLACKMAIL-036-own-credit-rollback-"+failure,()=>{var s=Make();Rows(s,new LedgerBlackmail(1,2,2,3,4));s.CurrentTurn=5;var before=Snap(s);var scope=Start(s);Fault.At=failure;Check(NativeBlackmail.Finished(null,scope)is not null&&P(s,1).Currency==20&&Snap(s).Bytes().SequenceEqual(before.Bytes()),"failed own credit restores treasury and independent stamp");});
   Test("BLACKMAIL-037-own-credit-save-reload-idempotence",()=>{var s=Make();Rows(s,new LedgerBlackmail(1,2,2,3,4));s.CurrentTurn=5;Marker(s);var saved=Snap(s);var loaded=Make();loaded.CurrentTurn=5;P(loaded,1).Currency=21;NativeGameStateEnvelope.Set(loaded,saved.Revision,saved.Bytes());Marker(loaded);Check(P(loaded,1).Currency==21,"reload cannot repeat collection");loaded.CurrentTurn=6;Marker(loaded);Check(P(loaded,1).Currency==22,"next own turn collects");});
   UnitBlackmailTests();
   EscalatingCostTests();
